ON CONFLICT (c_class_trib) DO UPDATE SET
    cst = EXCLUDED.cst,
    description = EXCLUDED.description,
    taxation_mode = EXCLUDED.taxation_mode,
    nfce_allowed = EXCLUDED.nfce_allowed,
    ibs_reduction_percent = EXCLUDED.ibs_reduction_percent,
    cbs_reduction_percent = EXCLUDED.cbs_reduction_percent,
    valid_from = EXCLUDED.valid_from,
    valid_to = EXCLUDED.valid_to,
    source_version = EXCLUDED.source_version,
    rate_type = EXCLUDED.rate_type,
    ind_g_ibs_cbs = EXCLUDED.ind_g_ibs_cbs,
    ind_g_ibs_cbs_mono = EXCLUDED.ind_g_ibs_cbs_mono,
    ind_g_reduction = EXCLUDED.ind_g_reduction,
    ind_g_deferral = EXCLUDED.ind_g_deferral,
    ind_g_transfer_credit = EXCLUDED.ind_g_transfer_credit,
    ind_g_presumed_credit_zfm = EXCLUDED.ind_g_presumed_credit_zfm,
    ind_g_competence_adjustment = EXCLUDED.ind_g_competence_adjustment,
    ind_base_reducer = EXCLUDED.ind_base_reducer,
    ind_regular_taxation = EXCLUDED.ind_regular_taxation,
    ind_presumed_credit_operation = EXCLUDED.ind_presumed_credit_operation,
    ind_mono_standard = EXCLUDED.ind_mono_standard,
    ind_mono_withholding = EXCLUDED.ind_mono_withholding,
    ind_mono_withheld = EXCLUDED.ind_mono_withheld,
    ind_biofuel_difference = EXCLUDED.ind_biofuel_difference,
    ind_credit_reversal = EXCLUDED.ind_credit_reversal,
    gross_revenue_type = EXCLUDED.gross_revenue_type,
    donation_type = EXCLUDED.donation_type,
    source_updated_at = EXCLUDED.source_updated_at;

DO $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
      FROM tb_ibs_cbs_tax_classification
     WHERE source_version = 'IT 2025.002 v1.70';

    IF v_count <> 173 THEN
        RAISE EXCEPTION 'Snapshot IT 2025.002 v1.70 incompleto: esperado 173 registros, encontrado %', v_count;
    END IF;

    IF EXISTS (
        SELECT 1 FROM tb_ibs_cbs_tax_classification
         WHERE source_version = 'IT 2025.002 v1.70'
           AND LEFT(c_class_trib, 3) <> cst
    ) THEN
        RAISE EXCEPTION 'Snapshot IT 2025.002 v1.70 contém cClassTrib incompatível com CST';
    END IF;
END $$;
